// Starter words and their synonyms, loaded from data/words.json.
//
// That file is generated by tools/wordbank (WordNet + Wiktionary + Moby + GloVe), so every ruling is the same
// for every player. Don't edit it by hand: fix tools/wordbank/graded/<word>.json and run `npm run words:build`.

import data from './data/words.json' with { type: 'json' };

export type Tier = 'easy' | 'medium' | 'hard';

/** How close a synonym is: 1 = core ("glad"), 2 = solid ("ecstatic"), 3 = distant ("upbeat"). */
export type Closeness = 1 | 2 | 3;

/** Which synonyms count in a game: Close = 1 only, Standard = 1–2, Loose = 1–3. */
export type Range = 'close' | 'standard' | 'loose';
export const RANGE_MAX: Record<Range, Closeness> = { close: 1, standard: 2, loose: 3 };

/** One meaning of a starter word, e.g. happy → "glad: enjoying or showing joy". */
export interface Sense {
  label: string;
  definition: string;
  pos: string;
}

export interface Synonym {
  word: string;
  closeness: Closeness;
  /** Index into the starter's `senses`. */
  sense: number;
  /** How rare the word is in everyday English: 1 common, 2 uncommon, 3 rare (worth bonus points). */
  rarity: 1 | 2 | 3;
}

export interface StarterWord {
  word: string;
  tier: Tier;
  senses: Sense[];
  synonyms: Synonym[];
  /** Related-but-wrong words that bots bluff with. */
  decoys: string[];
}

type Raw = [string, Tier, [string, string, string][], [string, Closeness, number, 1 | 2 | 3][], string[]];

export const STARTERS: StarterWord[] = (data.starters as Raw[]).map(([word, tier, senses, synonyms, decoys]) => ({
  word,
  tier,
  senses: senses.map(([label, definition, pos]) => ({ label, definition, pos })),
  synonyms: synonyms.map(([w, closeness, sense, rarity]) => ({ word: w, closeness, sense, rarity })),
  decoys,
}));

/** The synonyms that count in the given range. */
export function synonymsInRange(starter: StarterWord, range: Range): Synonym[] {
  return starter.synonyms.filter((s) => s.closeness <= RANGE_MAX[range]);
}

export function startersForTier(tier: Tier): StarterWord[] {
  return STARTERS.filter((s) => s.tier === tier);
}

/** How many players have already seen each starter word (words nobody has seen can be left out). */
export type SeenCounts = Record<string, number>;

const STARTER_WORDS = new Set(STARTERS.map((s) => s.word));

/**
 * Pick a starter word: never one already used this game, and among the rest one the fewest players have seen,
 * so nobody gets a word again until they've had every other word at that difficulty.
 */
export function pickStarter(pool: StarterWord[], used: readonly string[], seen: SeenCounts, rng: () => number): StarterWord {
  const fresh = pool.filter((s) => !used.includes(s.word));
  const from = fresh.length ? fresh : pool;
  const least = Math.min(...from.map((s) => seen[s.word] ?? 0));
  const best = from.filter((s) => (seen[s.word] ?? 0) === least);
  return best[Math.floor(rng() * best.length)];
}

/** A list of seen starter words from a browser (untrusted): known words only, no repeats. */
export function cleanSeen(x: unknown): string[] {
  if (!Array.isArray(x)) return [];
  return [...new Set(x.filter((w): w is string => typeof w === 'string' && STARTER_WORDS.has(w)))].slice(0, STARTERS.length);
}

/** Add up several players' seen lists. */
export function countSeen(lists: readonly (readonly string[])[]): SeenCounts {
  const counts: SeenCounts = {};
  for (const list of lists) for (const w of list) counts[w] = (counts[w] ?? 0) + 1;
  return counts;
}
